import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 7 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–6.
 */

// ─────────────────────── PRACTICE TEST 7 · R&W M1 (27) ───────────────────────
const T7_RW_M1: SatQuestion[] = [
  { id: "t7rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The chef's signature sauce was praised for its ______ flavor, balancing sweet, sour, and savory notes in a single spoonful.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["complex", "bland", "sour", "watery"], correct: 0, explanation: "The sentence says the sauce balances 'sweet, sour, and savory notes in a single spoonful,' so the blank needs a word meaning 'made of many interwoven parts.' 'Complex' (A) fits exactly: a complex flavor is one with multiple components working together. 'Bland' (B) means flavorless — the opposite of a sauce praised for balancing three distinct notes. 'Sour' (C) names only one of the three notes and ignores the 'balancing' idea, so it is far too narrow. 'Watery' (D) describes texture/dilution, not a praised multi-note flavor, and carries a negative tone that clashes with 'praised.' Answer: A." },
  { id: "t7rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The flock of geese ______ migrating south earlier than usual this autumn.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "Rule: subject–verb agreement. The grammatical subject is 'The flock,' a singular collective noun; the prepositional phrase 'of geese' is not the subject and cannot control the verb. A singular subject takes a singular verb, so 'is' (A) is correct. 'Are' (B) and 'were' (D) are plural and would wrongly agree with 'geese' instead of 'flock.' 'Have been' (C) is also plural and additionally distorts the tense, since the sentence describes a present situation ('this autumn'). Answer: A." },
  { id: "t7rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Mycorrhizal fungi link the roots of neighboring trees underground, ferrying water and nutrients between them in exchange for sugars the trees produce.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Fungi and trees trade resources through an underground network.", "Trees grow best when isolated from fungi.", "Fungi take nutrients from trees without giving anything back.", "Trees produce no sugars of their own."], correct: 0, explanation: "Main-idea question: the answer must capture the whole text, which says fungi 'ferry water and nutrients' to trees 'in exchange for sugars the trees produce' — a two-way exchange. Choice A ('Fungi and trees trade resources through an underground network') restates exactly this mutual trade and the 'underground' link. B contradicts the passage, which shows fungi help, not harm, neighboring trees. C is the opposite of 'in exchange' — the fungi do receive sugars, so the relationship is not one-sided. D contradicts the explicit phrase 'sugars the trees produce.' Answer: A." },
  { id: "t7rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The bridge was nearing the end of its safe lifespan. ______, engineers recommended replacing it within the decade.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "Transition logic: the first sentence is a cause (the bridge is nearing the end of its safe lifespan) and the second is its effect (engineers recommend replacing it). A cause-and-effect link needs a result transition, so 'Consequently' (B) is correct. 'Nevertheless' (A) and 'However' (C) signal contrast, but there is no contradiction — the recommendation agrees with the warning. 'In contrast' (D) likewise sets up an opposition that does not exist. Answer: B." },
  { id: "t7rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The recipe calls for three spices ______ cumin, coriander, and turmeric.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["spices, ", "spices: ", "spices; ", "spices "], correct: 1, explanation: "Rule: colon usage. A colon follows a complete independent clause ('The recipe calls for three spices') to introduce a list that specifies it — here, 'cumin, coriander, and turmeric.' So 'spices: ' (B) is correct. A comma (A) is too weak to introduce a formal list of items and creates a loose, unidiomatic break. A semicolon (C) must join two independent clauses, but 'cumin, coriander, and turmeric' is not a clause. No punctuation (D) runs the list directly into the noun without the needed introduction. Answer: B." },
  { id: "t7rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her travel journal was unusually ______, recording even the color of each train ticket she collected.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["thorough", "careless", "brief", "vague"], correct: 0, explanation: "The clue is 'recording even the color of each train ticket' — capturing tiny, exhaustive detail. The blank needs a word meaning 'complete and detailed,' which is 'thorough' (A). 'Careless' (B) is the opposite — someone careless would omit details, not record the color of every ticket. 'Brief' (C) contradicts a journal packed with minute particulars. 'Vague' (D) means imprecise, again the reverse of recording exact colors. Answer: A." },
  { id: "t7rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant funds research projects led only by scientists who have held a doctorate for at least five years; newer doctorate-holders are ineligible.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A scientist who earned a doctorate two years ago cannot lead a funded project.", "Every scientist qualifies for the grant.", "The grant funds projects led by students.", "Scientists with no doctorate are eligible."], correct: 0, explanation: "The text states the grant funds projects led only by scientists who have held a doctorate 'for at least five years,' and that 'newer doctorate-holders are ineligible.' A scientist who earned a doctorate two years ago has held it under five years, so cannot lead a funded project — choice A is directly supported. B ('every scientist qualifies') contradicts the stated five-year restriction. C ('students') is unsupported; the text requires a doctorate, not student status. D ('no doctorate are eligible') reverses the requirement — having a doctorate is mandatory. Answer: A." },
  { id: "t7rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The orchestra rehearsed for months. ______, it added a guest soloist for the final concert.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Transition logic: the first sentence says the orchestra rehearsed for months; the second adds a further step taken for the same concert (adding a guest soloist). These are two accumulating preparations, so an additive transition fits: 'In addition' (B). 'However' (A) signals contrast, but the two actions agree rather than conflict. 'Otherwise' (C) introduces an alternative/consequence ('if not, then…'), which the sentence does not set up. 'Instead' (D) implies the soloist replaced the rehearsing, but both happened. Answer: B." },
  { id: "t7rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Critics called the documentary ______, noting that it raised pointed questions without ever pretending to answer them.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["provocative", "tedious", "conclusive", "soothing"], correct: 0, explanation: "The clue is that the documentary 'raised pointed questions without ever pretending to answer them' — it stirs thought and challenges viewers. The precise word is 'provocative' (A), meaning designed to provoke reflection or reaction. 'Tedious' (B) means boring, which clashes with raising pointed, engaging questions. 'Conclusive' (C) means settling matters definitively — the exact opposite of a film that deliberately leaves questions unanswered. 'Soothing' (D) suggests calming, not the unsettling effect of pointed questions. Answer: A." },
  { id: "t7rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Octopuses can change both the color and the texture of their skin in under a second, blending almost perfectly with coral, sand, or rock.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Octopuses camouflage by rapidly altering their skin's color and texture.", "Octopuses cannot change their appearance.", "Octopuses are visible to all predators.", "Octopuses live only on sand."], correct: 0, explanation: "Main idea: the passage says octopuses change 'both the color and the texture of their skin in under a second, blending almost perfectly' with their surroundings — i.e., they camouflage by rapidly altering color and texture. Choice A captures both elements (color AND texture) and the purpose (blending in). B contradicts the text, which describes exactly such changes. C ('visible to all predators') reverses the point — the blending makes them hard to see. D ('only on sand') is unsupported; the text lists coral, sand, AND rock. Answer: A." },
  { id: "t7rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the runners ______ expected to finish the marathon within four hours.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "Rule: subject–verb agreement with indefinite pronouns. The subject is 'Each,' which is always grammatically singular, regardless of the plural 'of the runners' that follows. A singular subject takes the singular verb 'is' (A). 'Are' (B) and 'were' (C) are plural and wrongly agree with 'runners' instead of 'Each.' 'Have been' (D) is also plural and shifts the tense away from the simple present the sentence calls for. Answer: A." },
  { id: "t7rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup's first app failed to attract users. ______, its founders learned lessons that shaped a far more successful second product.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "Transition logic: the first sentence is negative (the app failed to attract users); the second is positive (the founders learned lessons that led to success). A bad outcome followed by an unexpected good one calls for a contrast/concession word: 'Still' (A), meaning 'even so.' 'For instance' (B) would require the second sentence to exemplify the first, but it does not. 'Therefore' (C) signals a logical result, yet learning valuable lessons does not simply follow from failing. 'In short' (D) introduces a summary, but the second sentence adds new information rather than condensing. Answer: A." },
  { id: "t7rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Survey results showed satisfaction at 62% in the city center, 78% in the suburbs, and 81% in rural areas of the county.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Satisfaction was lowest in the city center.", "Satisfaction was highest in the city center.", "Suburban satisfaction exceeded rural satisfaction.", "All three areas reported identical satisfaction."], correct: 0, explanation: "Read the three figures: city center 62%, suburbs 78%, rural 81%. The smallest is 62% (city center), so satisfaction was lowest there — choice A is supported. B says highest, but 62% is the lowest, not the highest. C claims suburban (78%) exceeded rural (81%), but 78 < 81, so rural was actually higher. D says all three were identical, which the three different numbers directly contradict. Answer: A." },
  { id: "t7rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The museum acquired a painting ______ had been hidden in a private collection for a century.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "Rule: relative pronoun choice. The blank introduces a relative clause modifying the thing 'painting,' so it needs the relative pronoun 'that' (A), which is used for things and serves as the subject of 'had been hidden.' 'What' (B) cannot follow and modify a stated noun; it means 'the thing which' and would leave 'painting' without a connector. 'Where' (C) is for places, but a painting is a thing, not a location. 'And it' (D) creates a comma-splice-style run-on (two clauses joined without proper subordination) and fails to attach the clause to 'painting.' Answer: A." },
  { id: "t7rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Walking onto the stage, ______ the bright lights made the singer pause for a moment.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["walking onto the stage, the bright lights made the singer pause", "the singer paused as she walked onto the stage, blinded by the bright lights", "the bright lights, walking onto the stage, made her pause", "pausing, the bright lights blinded the singer onto the stage"], correct: 1, explanation: "Rule: modifier placement (dangling modifier). The opening phrase 'Walking onto the stage' must be immediately followed by the noun performing that action — the person who walks. Only the singer can walk, so 'the singer' must come right after the modifier. Choice B ('the singer paused as she walked onto the stage, blinded by the bright lights') correctly attaches the action to the singer. A leaves 'the bright lights' walking onto the stage — lights cannot walk (dangling modifier). C has 'the bright lights … walking onto the stage,' the same error. D places 'the bright lights' after 'pausing,' so the lights are pausing — illogical. Answer: B." },
  { id: "t7rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers argue that frequent note-taking by hand, though slower than typing, leads to deeper understanding because writers must summarize rather than transcribe.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Students who handwrote notes scored higher on conceptual questions than those who typed.", "Typing notes is faster than writing them by hand.", "Most students prefer typing to handwriting.", "Handwriting and typing produce the same word count."], correct: 0, explanation: "The claim to strengthen is that handwriting notes 'leads to deeper understanding.' Evidence that strengthens it must link handwriting to better understanding. Choice A — students who handwrote scored higher on conceptual questions — directly shows deeper understanding, so it strengthens the claim. B (typing is faster) is conceded in the passage and says nothing about understanding. C (students prefer typing) concerns preference, not comprehension, and if anything cuts against the claim. D (same word count) measures quantity, not understanding, and is irrelevant to the depth argument. Answer: A." },
  { id: "t7rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The architect, along with her two assistants, ______ presenting the final plans tomorrow.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "Rule: subject–verb agreement with intervening phrases. The subject is the singular 'The architect.' The phrase 'along with her two assistants' is set off by commas and is NOT part of the grammatical subject — unlike 'and,' phrases such as 'along with,' 'as well as,' and 'together with' do not make a subject plural. So the verb stays singular: 'is' (A). 'Are' (B) and 'were' (C) are plural, wrongly agreeing with 'assistants.' 'Have been' (D) is plural and also distorts the present tense signaled by 'tomorrow.' Answer: A." },
  { id: "t7rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A scientist wants to emphasize that two unrelated experiments reached the same conclusion. ______, both teams found that the enzyme degraded above 40°C.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Notably", "However", "Otherwise"], correct: 1, explanation: "Transition logic: the goal is to emphasize that two unrelated experiments reached the SAME conclusion, and the second sentence reports that agreement (both found the enzyme degraded above 40°C). A word that highlights a striking point fits: 'Notably' (B). 'By contrast' (A) signals opposition, but the two results agree, not differ. 'However' (C) likewise sets up a contradiction that is not present. 'Otherwise' (D) means 'if not,' introducing an alternative scenario, which does not match the emphasis on shared findings. Answer: B." },
  { id: "t7rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The poem's final stanza is deliberately ______: each reader leaves with a different sense of whether the speaker has found peace.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["open-ended", "literal", "repetitive", "cheerful"], correct: 0, explanation: "The clue is that 'each reader leaves with a different sense' of the outcome — the stanza invites multiple interpretations rather than settling the question. 'Open-ended' (A) means precisely this: left for the reader to resolve. 'Literal' (B) means plain and exact in meaning, which would produce one reading, not many. 'Repetitive' (C) describes repetition of words/ideas, unrelated to interpretive ambiguity. 'Cheerful' (D) names a mood and says nothing about differing reader interpretations. Answer: A." },
  { id: "t7rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The new tax credit is available only to households that installed solar panels after 2023 and that earn below the county median income.", prompt: "Which household clearly qualifies for the credit?", type: "mcq", choices: ["A below-median-income household that installed panels in 2024.", "A high-income household that installed panels in 2024.", "A below-median-income household that installed panels in 2019.", "A household that has never installed panels."], correct: 0, explanation: "The credit requires BOTH conditions: panels installed 'after 2023' AND income 'below the county median.' Test each option. A: below-median income AND installed in 2024 (after 2023) — both met, so it qualifies. B: installed in 2024 (good) but high income — fails the income test. C: below-median income (good) but installed in 2019, before 2023 — fails the date test. D: never installed panels — fails both. Only A satisfies both conditions. Answer: A." },
  { id: "t7rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The volunteers cleaned the riverbank ______ they planted native grasses along the slope.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["riverbank, and then", "riverbank and, then", "riverbank then", "riverbank, then"], correct: 0, explanation: "Rule: joining two independent clauses. 'The volunteers cleaned the riverbank' and 'they planted native grasses along the slope' are both complete clauses. A correct join uses a comma plus a coordinating conjunction (FANBOYS), so 'riverbank, and then' (A) is right — the comma precedes 'and.' 'riverbank and, then' (B) misplaces the comma after the conjunction, which is ungrammatical. 'riverbank then' (C) joins two clauses with only 'then,' an adverb, producing a run-on. 'riverbank, then' (D) joins two independent clauses with just a comma — a comma splice. Answer: A." },
  { id: "t7rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although she was known for her ______ remarks, the columnist could be surprisingly gentle when reviewing first novels.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["caustic", "tender", "hesitant", "muted"], correct: 0, explanation: "The word 'Although' sets up a contrast with 'surprisingly gentle,' so the blank must describe remarks that are the opposite of gentle — harsh or biting. 'Caustic' (A) means cuttingly critical, the right contrast. 'Tender' (B) is a synonym for gentle, so it ruins the 'Although' contrast. 'Hesitant' (C) means uncertain, which is not the opposite of gentle and doesn't fit 'known for.' 'Muted' (D) means subdued/quiet, again not a contrast with 'gentle.' Answer: A." },
  { id: "t7rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A historian notes that medieval towns built near rivers grew faster than inland towns, attributing the gap to easier trade and transport.", prompt: "Which choice best describes the historian's explanation?", type: "mcq", choices: ["River access aided trade and transport, fueling faster growth.", "Inland towns had better trade routes.", "Rivers slowed the growth of nearby towns.", "Town location had no effect on growth."], correct: 0, explanation: "The text says river towns 'grew faster than inland towns' and the historian attributes 'the gap to easier trade and transport.' Choice A restates this: river access aided trade and transport, fueling faster growth. B reverses the claim — the text says inland towns grew slower, not that they had better routes. C contradicts the passage, which credits rivers with FASTER, not slower, growth. D denies any location effect, but the historian explicitly ties location (river vs. inland) to growth. Answer: A." },
  { id: "t7rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee postponed its decision ______ it lacked the data needed to choose between the two sites.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["decision because", "decision, because", "decision; because", "decision: because"], correct: 0, explanation: "Rule: no punctuation before a trailing dependent clause. 'The committee postponed its decision' is the main clause, and 'because it lacked the data…' is a dependent clause that follows it. When a 'because'-clause comes AFTER the main clause and is essential to the meaning, no punctuation precedes it, so 'decision because' (A) is correct. A comma (B) is unnecessary and wrongly separates the cause from the main clause. A semicolon (C) requires an independent clause after it, but 'because…' is dependent. A colon (D) must follow a complete statement to introduce an explanation/list, and 'because' already supplies the connection, making the colon incorrect. Answer: A." },
  { id: "t7rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory cut its energy use by half. ______, it reduced its annual operating costs by nearly a million dollars.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "Transition logic: the first sentence is a cause (the factory halved its energy use) and the second is the effect (it cut operating costs by nearly a million dollars). A result transition is needed: 'As a result' (A). 'Nevertheless' (B) signals contrast, but the cost savings agree with — rather than oppose — the energy cut. 'For example' (C) would require the second sentence to illustrate the first, but it states a consequence, not an instance. 'On the other hand' (D) introduces a contrasting point, which is not present. Answer: A." },
  { id: "t7rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The mentor offered ______ advice, the kind a student could actually apply the very next morning.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["practical", "abstract", "confusing", "irrelevant"], correct: 0, explanation: "The clue is 'the kind a student could actually apply the very next morning' — usable, hands-on advice. 'Practical' (A) means exactly that: directly applicable in real situations. 'Abstract' (B) means theoretical and removed from application — the opposite of advice you can use immediately. 'Confusing' (C) would make advice hard to apply, contradicting the clue. 'Irrelevant' (D) means not useful or pertinent, again clashing with advice a student could apply right away. Answer: A." },
  { id: "t7rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A field study found that wolves' return to a valley reduced the elk population, which in turn allowed young willow trees — once overgrazed — to recover along the streams.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Restoring wolves triggered a chain of effects that helped willows recover.", "Wolves directly planted the willow trees.", "Elk populations grew after the wolves returned.", "Willows declined once the wolves arrived."], correct: 0, explanation: "Main idea: the text describes a chain — wolves return, elk population drops, and the once-overgrazed willows then recover. Choice A ('Restoring wolves triggered a chain of effects that helped willows recover') captures this multi-step cause and effect. B says wolves 'directly planted' the willows, but wolves don't plant trees; the effect is indirect, through elk. C claims elk grew, but the text says wolves REDUCED the elk population. D says willows declined after the wolves arrived, the reverse of the recovery the text reports. Answer: A." },
];

// ─────────────────────── PRACTICE TEST 7 · R&W M2 easy (27) ──────────────────
const T7_RW_M2E: SatQuestion[] = [
  { id: "t7rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup was too ______, so I added some cold water to cool it down.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["hot", "sweet", "blue", "loud"], correct: 0, explanation: "The clue 'added some cold water to cool it down' tells us the soup needed cooling, so it was too 'hot' (A). 'Sweet' (B) describes taste, not temperature, and cold water wouldn't fix sweetness. 'Blue' (C) is a color and has nothing to do with cooling. 'Loud' (D) describes sound and makes no sense for soup. Answer: A." },
  { id: "t7rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The two cats ______ sleeping on the warm windowsill.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Rule: subject–verb agreement. The subject 'The two cats' is plural, so it needs a plural present-tense verb: 'are' (B). 'Is' (A) is singular and would only fit a single cat. 'Was' (C) is singular past tense — wrong number and wrong for the ongoing present action ('sleeping'). 'Am' (D) is used only with 'I.' Answer: B." },
  { id: "t7rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Penguins cannot fly, but their wings act like flippers that help them swim quickly through the water.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Penguins use their wings to swim rather than to fly.", "Penguins fly long distances every year.", "Penguins cannot move in water.", "Penguins have no wings at all."], correct: 0, explanation: "Main idea: the text says penguins 'cannot fly, but their wings act like flippers that help them swim quickly.' Choice A states exactly this — wings used to swim, not fly. B contradicts 'cannot fly.' C says penguins cannot move in water, but the text says they swim quickly. D claims they have no wings, but the text explicitly mentions their wings. Answer: A." },
  { id: "t7rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The library was closing in ten minutes. ______, I quickly checked out my book.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "Transition logic: the first sentence is a cause (the library was closing in ten minutes) and the second is the effect (I quickly checked out my book). A result transition fits: 'So' (B). 'For example' (A) would need the second sentence to illustrate the first, but it states a consequence. 'However' (C) signals contrast, yet hurrying agrees with the closing deadline. 'Meanwhile' (D) marks simultaneous, unrelated events, not cause and effect. Answer: B." },
  { id: "t7rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last week we ______ a movie at the new theater downtown.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["watch", "watches", "watched", "watching"], correct: 2, explanation: "Rule: verb tense. The time marker 'Last week' places the action in the past, so the simple past 'watched' (C) is correct. 'Watch' (A) is present tense and clashes with 'Last week.' 'Watches' (B) is third-person singular present — wrong tense and wrong for the subject 'we.' 'Watching' (D) is a participle that cannot stand alone as the main verb without a helping verb. Answer: C." },
  { id: "t7rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The garden was full of ______ flowers in red, yellow, and purple.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["colorful", "dull", "broken", "empty"], correct: 0, explanation: "The clue 'in red, yellow, and purple' lists many colors, so the flowers were 'colorful' (A). 'Dull' (B) means lacking brightness — the opposite of multiple vivid colors. 'Broken' (C) describes damage, not color. 'Empty' (D) means containing nothing, which contradicts a garden 'full of' flowers. Answer: A." },
  { id: "t7rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Recycling paper saves trees, reduces waste in landfills, and uses less energy than making new paper.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Recycling paper offers several environmental benefits.", "Recycling paper harms the environment.", "Recycling paper only saves trees.", "Making new paper is always better."], correct: 0, explanation: "Main idea: the text lists three positives of recycling paper — it 'saves trees, reduces waste in landfills, and uses less energy.' Choice A captures all of these as 'several environmental benefits.' B says it harms the environment, the opposite of the listed benefits. C ('only saves trees') ignores the other two benefits, so it is too narrow. D praises making new paper, which the text actually presents as worse (more energy). Answer: A." },
  { id: "t7rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She waited for ______ hour before the bus finally arrived.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Rule: 'a' vs. 'an' depends on the SOUND that follows, not the letter. 'Hour' has a silent 'h,' so it begins with a vowel sound ('our'), which takes 'an' (B). 'A' (A) precedes consonant sounds, so 'a hour' is wrong. 'The only' (C) changes the meaning (implying a single specific hour) and doesn't fit the neutral statement. 'Some' (D) is vague and pairs awkwardly with the singular 'hour' here. Answer: B." },
  { id: "t7rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The test was ______, so most students finished early and felt confident.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["easy", "impossible", "endless", "frightening"], correct: 0, explanation: "The clue 'most students finished early and felt confident' signals a test that wasn't hard, so 'easy' (A). 'Impossible' (B) means it couldn't be done — students wouldn't finish early and feel confident. 'Endless' (C) implies it never finished, contradicting 'finished early.' 'Frightening' (D) clashes with feeling confident. Answer: A." },
  { id: "t7rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My brother and I ______ going to the beach this weekend.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Rule: subject–verb agreement with a compound subject. 'My brother and I' is joined by 'and,' making it plural, so it takes the plural verb 'are' (B). 'Is' (A) and 'was' (C) are singular and don't agree with the two-person subject. 'Am' (D) is used only with 'I' alone, not with a compound subject. Answer: B." },
  { id: "t7rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Camels store fat in their humps, which their bodies can use for energy when food and water are scarce.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A camel's hump stores fat the camel can use when resources are scarce.", "A camel's hump stores water only.", "Camels never need food.", "Camels cannot survive in deserts."], correct: 0, explanation: "Main idea: the text says camels 'store fat in their humps,' which 'their bodies can use for energy when food and water are scarce.' Choice A restates this — the hump stores fat usable when resources run low. B says the hump stores 'water only,' but the text says it stores fat. C ('never need food') overstates and contradicts the idea that stored fat is a backup for scarce times. D ('cannot survive in deserts') contradicts the whole point — this adaptation helps them survive there. Answer: A." },
  { id: "t7rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It started to snow heavily. ______, the school announced an early dismissal.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "Transition logic: heavy snow (cause) led to the school's early dismissal (effect), so a result transition is needed: 'As a result' (B). 'However' (A) signals contrast, but the dismissal follows naturally from the snow. 'For example' (C) would require the second sentence to be an instance of the first, which it isn't. 'Instead' (D) implies a replacement/alternative, not a consequence. Answer: B." },
  { id: "t7rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the team ______ its first game of the season.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["win", "wins", "won", "winning"], correct: 2, explanation: "Rule: verb tense. The time marker 'Yesterday' places the action in the past, so the simple past 'won' (C) is correct. 'Win' (A) is present tense and conflicts with 'Yesterday.' 'Wins' (B) is third-person singular present — wrong tense. 'Winning' (D) is a participle that cannot serve as the main verb without a helping verb. Answer: C." },
  { id: "t7rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After running the race, the athlete felt ______ and sat down to rest.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["exhausted", "energetic", "bored", "amused"], correct: 0, explanation: "The clue 'sat down to rest' after running a race signals tiredness, so 'exhausted' (A). 'Energetic' (B) is the opposite — an energetic athlete wouldn't need to rest. 'Bored' (C) describes a state of mind unrelated to physical exertion. 'Amused' (D) means entertained, which doesn't explain needing to rest. Answer: A." },
  { id: "t7rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The store is open from 9 a.m. to 6 p.m. on weekdays but stays closed on Sundays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["You cannot shop at the store on Sunday.", "The store opens at midnight.", "The store is open every day.", "The store closes at 9 a.m."], correct: 0, explanation: "The text says the store 'stays closed on Sundays,' so you cannot shop there on Sunday — choice A is directly supported. B ('opens at midnight') contradicts the stated 9 a.m. weekday opening. C ('open every day') contradicts the Sunday closure. D ('closes at 9 a.m.') misreads the hours — 9 a.m. is the opening time, and closing is 6 p.m. Answer: A." },
  { id: "t7rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The dog wagged ______ tail when its owner came home.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Rule: possessive pronoun vs. contraction. The blank needs a singular possessive to show the tail belongs to the dog: 'its' (A), the possessive form. 'It's' (B) is the contraction of 'it is' ('the dog wagged it is tail' is nonsense). 'Their' (C) is plural and doesn't agree with the singular 'dog.' 'They're' (D) is the contraction of 'they are' — neither possessive nor singular. Answer: A." },
  { id: "t7rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Many plants need sunlight to grow. ______, sunflowers turn to face the sun throughout the day.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Transition logic: the first sentence makes a general statement (plants need sunlight), and the second gives a specific instance (sunflowers turn to face the sun). An illustration transition fits: 'For example' (A). 'However' (B) signals contrast, but the example agrees with the general claim. 'Instead' (C) implies a substitution, not an example. 'Otherwise' (D) means 'if not,' introducing a condition, which doesn't match. Answer: A." },
  { id: "t7rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The room was very ______, so we turned on every lamp we could find.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["dark", "bright", "warm", "loud"], correct: 0, explanation: "The clue 'turned on every lamp we could find' means the room lacked light, so it was 'dark' (A). 'Bright' (B) is the opposite — a bright room wouldn't need lamps. 'Warm' (C) describes temperature, not light, so lamps wouldn't be the fix. 'Loud' (D) describes sound, unrelated to turning on lamps. Answer: A." },
  { id: "t7rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The boxes ______ stacked neatly against the back wall.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Rule: subject–verb agreement. The subject 'The boxes' is plural, so it needs the plural verb 'are' (B). 'Is' (A) and 'was' (C) are singular and don't agree with the plural 'boxes.' 'Am' (D) is used only with 'I.' Answer: B." },
  { id: "t7rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Honey never spoils; jars of it thousands of years old have been found still safe to eat.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Honey can remain edible for a very long time.", "Honey spoils within days.", "Honey is unsafe to eat.", "Honey cannot be stored in jars."], correct: 0, explanation: "The text says 'Honey never spoils' and that thousand-year-old jars are 'still safe to eat,' so honey stays edible for a very long time — choice A. B ('spoils within days') directly contradicts 'never spoils.' C ('unsafe to eat') contradicts 'still safe to eat.' D ('cannot be stored in jars') contradicts the mention of 'jars of it.' Answer: A." },
  { id: "t7rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We wanted to leave early. ______, traffic delayed us by an hour.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Transition logic: the first sentence states an intention (we wanted to leave early), and the second states an opposing outcome (traffic delayed us). This contradiction needs a contrast transition: 'However' (A). 'Therefore' (B) signals a result, but a delay does not follow from wanting to leave early. 'For example' (C) would need the second sentence to illustrate the first. 'Similarly' (D) signals agreement, but the two ideas conflict. Answer: A." },
  { id: "t7rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next summer my family ______ to visit the national park.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "Rule: subject–verb agreement. 'My family' is a singular collective noun, so it takes the third-person singular verb 'plans' (B); the present tense with 'next summer' expresses a scheduled future. 'Plan' (A) is the plural/base form and doesn't agree with the singular 'family.' 'Planned' (C) is past tense, contradicting 'Next summer.' 'Planning' (D) is a participle that cannot stand as the main verb without a helping verb. Answer: B." },
  { id: "t7rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new phone is very ______; it weighs less than a deck of cards.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["light", "heavy", "loud", "wide"], correct: 0, explanation: "The clue 'it weighs less than a deck of cards' means very little weight, so 'light' (A). 'Heavy' (B) is the opposite of weighing almost nothing. 'Loud' (C) describes sound, not weight. 'Wide' (D) describes width, not weight. Answer: A." },
  { id: "t7rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Reading aloud to young children helps them learn new words, recognize letters, and enjoy stories.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Reading aloud to children supports their learning in several ways.", "Reading aloud confuses children.", "Children should never be read to.", "Reading aloud only teaches letters."], correct: 0, explanation: "Main idea: the text lists three ways reading aloud helps children — it helps them 'learn new words, recognize letters, and enjoy stories.' Choice A captures all three as 'supports their learning in several ways.' B ('confuses children') contradicts the benefits listed. C ('should never be read to') reverses the positive message. D ('only teaches letters') ignores the words and enjoyment benefits, so it is too narrow. Answer: A." },
  { id: "t7rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She bought ______ umbrella before the storm arrived.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "Rule: 'a' vs. 'an' depends on the following sound. 'Umbrella' begins with a vowel sound ('uh'), which takes 'an' (B). 'A' (A) precedes consonant sounds, so 'a umbrella' is wrong. 'The only' (C) changes the meaning to a single specific umbrella and doesn't fit. 'Some' (D) is vague and awkward with the singular 'umbrella' here. Answer: B." },
  { id: "t7rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The recipe was simple to follow. ______, it took only twenty minutes to make.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "Transition logic: the first sentence gives one positive point (the recipe was simple to follow) and the second adds another positive (it took only twenty minutes). Two accumulating positives need an additive transition: 'In addition' (A). 'However' (B) signals contrast, but both points agree. 'Instead' (C) implies a substitution, not an added point. 'Otherwise' (D) means 'if not,' which doesn't fit. Answer: A." },
  { id: "t7rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The crowd was ______ when the home team scored the winning goal.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["thrilled", "silent", "bored", "tired"], correct: 0, explanation: "The clue 'home team scored the winning goal' is a joyful moment for fans, so the crowd was 'thrilled' (A). 'Silent' (B) is the opposite reaction to a winning goal. 'Bored' (C) clashes with an exciting decisive score. 'Tired' (D) describes fatigue, not the excitement a winning goal produces. Answer: A." },
];

// ─────────────────────── PRACTICE TEST 7 · R&W M2 hard (27) ──────────────────
const T7_RW_M2H: SatQuestion[] = [
  { id: "t7rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The senator's apology was so ______ that it managed to acknowledge the harm while quietly denying any personal fault.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "sincere", "blunt", "wholehearted"], correct: 0, explanation: "The apology 'acknowledge[s] the harm while quietly denying any personal fault' — it points two ways at once, which is the definition of 'equivocal' (A): deliberately ambiguous or hedging. 'Sincere' (B) means genuine and wholehearted, contradicting the hidden denial of fault. 'Blunt' (C) means direct and plainspoken, the opposite of an apology that 'quietly' dodges responsibility. 'Wholehearted' (D) means fully committed, which conflicts with denying fault. Answer: A." },
  { id: "t7rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The essay devotes its first half to vivid anecdotes before stepping back, in the second half, to draw a single general principle from them.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from specific examples to a broader generalization.", "It begins with a thesis and never supports it.", "It lists definitions without examples.", "It repeats one anecdote throughout."], correct: 0, explanation: "Structure question: the essay gives 'vivid anecdotes' in the first half, then 'step[s] back … to draw a single general principle from them.' That is a movement from specific examples to a broader generalization — choice A. B says it begins with a thesis and never supports it, but the essay ends with the principle, supported by the anecdotes. C says it lists definitions without examples, yet the text is built ON examples. D says it repeats one anecdote, but the text describes multiple anecdotes leading to one principle. Answer: A." },
  { id: "t7rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A battery held 92% capacity after 100 charge cycles, 90% after 200 cycles, and 75% after 500 cycles.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Capacity fell more steeply between 200 and 500 cycles than before.", "Capacity rose as cycles increased.", "Capacity stayed exactly constant.", "The battery was dead by 200 cycles."], correct: 0, explanation: "Read the data: 92% at 100 cycles, 90% at 200 cycles, 75% at 500 cycles. From 100 to 200 cycles, capacity dropped 2 points over 100 cycles (0.02/cycle). From 200 to 500 cycles, it dropped 15 points over 300 cycles (0.05/cycle) — a much steeper rate per cycle. So choice A (steeper decline between 200 and 500) is supported. B says capacity rose, but it fell at every step. C says it stayed constant, contradicting the changing numbers. D says the battery was dead by 200 cycles, but it still held 90% then. Answer: A." },
  { id: "t7rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The proposal would cut commute times dramatically. ______, it would route the new highway through a protected wetland.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "Transition logic: the first sentence is a benefit (the proposal would cut commute times), and the second is a serious drawback (it would route the highway through a protected wetland). A benefit set against a drawback needs a contrast transition: 'However' (B). 'Therefore' (A) and 'Accordingly' (D) signal results, but the wetland harm is not a consequence of shorter commutes. 'Likewise' (C) signals similarity, yet the two ideas oppose each other. Answer: B." },
  { id: "t7rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The workshop trains volunteers to plan events, to manage budgets, and ______ donors effectively.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to recruit", "recruiting", "recruit", "recruited"], correct: 0, explanation: "Rule: parallelism. The sentence lists three things the workshop trains volunteers to do: 'to plan events, to manage budgets, and ___ donors.' The first two items use the infinitive form ('to plan,' 'to manage'), so the third must match: 'to recruit' (A). 'Recruiting' (B) is a gerund, breaking the infinitive pattern. 'Recruit' (C) drops the 'to,' so it doesn't parallel the other items. 'Recruited' (D) is past tense and also non-parallel. Answer: A." },
  { id: "t7rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The biography refuses to ______ its subject, presenting his failures as candidly as his triumphs.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["idealize", "criticize", "describe", "remember"], correct: 0, explanation: "The biography presents his failures 'as candidly as his triumphs,' so it refuses to portray him as flawless — it refuses to 'idealize' (A) him. 'Criticize' (B) is wrong: refusing to criticize would mean hiding failures, but the book shows them. 'Describe' (C) is illogical — the book clearly does describe him. 'Remember' (D) doesn't fit 'refuses to,' since the biography is an act of remembering. Answer: A." },
  { id: "t7rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the older theory treated memory as a faithful recording, the newer model casts it as an act of reconstruction shaped by present beliefs.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of memory with a newer, reconstructive one.", "To prove memory is a perfect recording.", "To summarize only the older theory.", "To argue memory does not exist."], correct: 0, explanation: "Purpose question: the structure 'Where the older theory treated … the newer model casts …' sets two views side by side — memory as a 'faithful recording' versus an 'act of reconstruction.' That is a contrast of an older and a newer view, so choice A. B says it proves memory is a perfect recording, but the newer model rejects that. C says it summarizes only the older theory, ignoring the newer one. D says memory doesn't exist, which the text never claims. Answer: A." },
  { id: "t7rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The morning shift handled the surge of orders smoothly ______ the evening shift struggled with the very same volume.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["smoothly, the", "smoothly; the", "smoothly the", "smoothly: the"], correct: 1, explanation: "Rule: joining two independent clauses. 'The morning shift handled the surge of orders smoothly' and 'the evening shift struggled with the very same volume' are both complete clauses. A semicolon correctly links two closely related independent clauses, so 'smoothly; the' (B) is right. 'smoothly, the' (A) joins two clauses with only a comma — a comma splice. 'smoothly the' (C) has no punctuation — a run-on. 'smoothly: the' (D) misuses a colon, which should introduce an explanation or list, not a contrasting clause of equal weight. Answer: B." },
  { id: "t7rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the author's prose is dense with allusions that reward, and sometimes demand, a second reading.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["transparent", "intricate", "layered", "demanding"], correct: 0, explanation: "'Far from being ___' signals that the prose is the OPPOSITE of the blank. The prose is 'dense with allusions' and 'demand[s] a second reading' — i.e., difficult, not easy to grasp. The opposite of difficult-and-dense is 'transparent' (A), meaning easily understood. The trap is B 'intricate,' C 'layered,' and D 'demanding' — all of which DESCRIBE the dense prose rather than being its opposite, so each contradicts the 'Far from' frame. Only 'transparent' is the clarity the prose lacks. Answer: A." },
  { id: "t7rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Critics claim the policy raised wages without reducing employment. Yet in the year it took effect, hiring at affected firms fell by 4%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It offers evidence that complicates the critics' claim.", "It restates the critics' claim word for word.", "It confirms that employment was unaffected.", "It proposes a new policy."], correct: 0, explanation: "Function question: the first sentence reports the critics' claim (the policy raised wages 'without reducing employment'). The second begins with 'Yet' and reports that hiring 'fell by 4%' — evidence that pushes against the no-employment-effect claim. So choice A: it offers evidence that complicates the critics' claim. B says it restates the claim word for word, but it introduces opposing data. C says it confirms employment was unaffected, the opposite of a 4% hiring drop. D says it proposes a new policy, which it does not. Answer: A." },
  { id: "t7rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The expedition's success depended on three things ______ favorable weather, ample supplies, and an experienced guide.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["things,", "things:", "things;", "things"], correct: 1, explanation: "Rule: colon usage. 'The expedition's success depended on three things' is a complete independent clause, and a colon introduces the list that specifies those things: 'favorable weather, ample supplies, and an experienced guide.' So 'things:' (B) is correct. A comma (A) is too weak to formally introduce the list. A semicolon (C) must join two independent clauses, but the list is not a clause. No punctuation (D) runs the list directly into 'things' without the needed break. Answer: B." },
  { id: "t7rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The model predicted the storm's path with impressive accuracy. ______, it failed to anticipate the storm's rapid intensification.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "Transition logic: the first sentence is a success (the model predicted the storm's path accurately), and the second is a failure (it missed the rapid intensification). A success followed by an opposing shortcoming needs a concessive/contrast transition: 'Nonetheless' (B). 'Indeed' (A) emphasizes/affirms the prior point, but the second sentence undercuts it. 'Therefore' (C) signals a result, yet the failure does not follow from the success. 'Likewise' (D) signals similarity, but the two ideas conflict. Answer: B." },
  { id: "t7rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, plants given the new fertilizer grew 30% taller than untreated plants, but they also produced 20% fewer flowers.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The fertilizer increased height but reduced flowering.", "The fertilizer increased both height and flowering.", "The fertilizer had no measurable effect.", "Untreated plants grew taller than treated ones."], correct: 0, explanation: "Read the data: fertilized plants grew '30% taller' but produced '20% fewer flowers.' So the fertilizer increased height while reducing flowering — choice A. B says it increased both height and flowering, but flowering dropped 20%. C says no measurable effect, contradicting the +30% and −20% figures. D says untreated plants grew taller, but the treated plants were 30% taller. Answer: A." },
  { id: "t7rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The painting that hangs above the fireplace ______ to the artist's earliest period, long before her famous murals.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "Rule: subject–verb agreement across an intervening clause. The subject is the singular 'The painting'; the relative clause 'that hangs above the fireplace' and the later noun 'murals' are distractors that do not control the main verb. A singular subject takes the singular 'belongs' (B). 'Belong' (A) is plural and would wrongly agree with 'murals.' 'Belonging' (C) is a participle, not a finite main verb. 'To belong' (D) is an infinitive and cannot serve as the sentence's main verb. Answer: B." },
  { id: "t7rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The diplomat's reputation for ______ — for saying precisely what was needed and not a word more — made her a sought-after negotiator.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["concision", "verbosity", "indecision", "flattery"], correct: 0, explanation: "The dash-set definition — 'saying precisely what was needed and not a word more' — describes brevity and economy of speech, which is 'concision' (A). 'Verbosity' (B) is the opposite: using too many words. 'Indecision' (C) means inability to decide, unrelated to word economy. 'Flattery' (D) means excessive praise, which doesn't match saying only what's needed. Answer: A." },
  { id: "t7rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author opens by granting that early computers were enormous and unreliable, then argues that these very limitations spurred the innovations that made them small and dependable.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It turns an apparent weakness into the source of later strengths.", "It denies that early computers had any flaws.", "It claims computers never improved.", "It lists computer prices over time."], correct: 0, explanation: "Reasoning question: the author grants early computers 'were enormous and unreliable,' then argues 'these very limitations spurred the innovations' that made them small and dependable. So a weakness is turned into the source of later strengths — choice A. B says it denies the flaws, but the author concedes them. C says computers never improved, contradicting the claim that they became small and dependable. D says it lists prices over time, which the text never does. Answer: A." },
  { id: "t7rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having trained for years on quiet mountain trails ______ the marathon's crowded city streets felt overwhelming.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the marathon's crowded city streets felt overwhelming", "the runner found the marathon's crowded city streets overwhelming", "overwhelming were the marathon's crowded streets", "it was overwhelming, the crowded streets"], correct: 1, explanation: "Rule: modifier placement (dangling modifier). The opening phrase 'Having trained for years on quiet mountain trails' must be followed immediately by the noun that did the training — a person. Only 'the runner' can train, so choice B ('the runner found the marathon's crowded city streets overwhelming') correctly attaches the action. A has 'the marathon's crowded city streets' doing the training — streets cannot train (dangling). C puts 'overwhelming' first and never supplies a trainer right after the modifier. D leads with 'it,' which cannot be the one who trained. Answer: B." },
  { id: "t7rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The drug shrank tumors in the laboratory dish. ______, results in living animals were far more modest, and human trials have not yet begun.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In living organisms, however", "For this reason", "Similarly"], correct: 1, explanation: "Transition logic: the first sentence reports strong lab-dish results (the drug shrank tumors), while the second reports weaker results in living animals plus no human trials. This is a contrast, and 'In living organisms, however' (B) both signals the contrast ('however') and frames the new setting. 'Consequently' (A) and 'For this reason' (C) signal results, but the weaker animal results don't follow from the dish success. 'Similarly' (D) signals agreement, yet the two outcomes differ. Answer: B." },
  { id: "t7rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic praised the album's ______ qualities, noting how a single melodic phrase resurfaces, transformed, in nearly every track.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unifying", "discordant", "random", "monotonous"], correct: 0, explanation: "The clue is that 'a single melodic phrase resurfaces, transformed, in nearly every track' — one element ties the album together, giving it 'unifying' (A) qualities. 'Discordant' (B) means clashing/disharmonious, the opposite of a coherent recurring theme. 'Random' (C) contradicts a deliberate phrase recurring across tracks. 'Monotonous' (D) implies tedious sameness, but the phrase appears 'transformed,' i.e., with variation, so it isn't monotonous. Answer: A." },
  { id: "t7rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across four cities, libraries that extended their evening hours saw checkouts rise by an average of 18%, while those that kept the same hours saw no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Extending evening hours was associated with higher checkouts.", "Shorter hours raised checkouts.", "Library hours had no relationship to checkouts.", "All libraries kept the same hours."], correct: 0, explanation: "Read the data: across four cities, libraries that extended evening hours saw checkouts rise '18%,' while those keeping the same hours saw 'no change.' This links extended hours to higher checkouts — choice A (note 'was associated with,' a careful correlational claim the data supports). B says shorter hours raised checkouts, but the data show extended hours did. C says hours had no relationship, contradicting the 18% gap. D says all libraries kept the same hours, but some extended them. Answer: A." },
  { id: "t7rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The novelist's early stories — sharp, spare, and quietly funny ______ already showed the voice that her later work would refine.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["stories —", "stories,", "stories", "stories;"], correct: 0, explanation: "Rule: paired punctuation around a nonessential interrupter. The phrase 'sharp, spare, and quietly funny' is a parenthetical description set off by an opening dash after 'stories.' A dash that opens an interrupter must be closed by a matching dash, so 'stories —' (A) is correct. A comma (B) cannot close a dash — punctuation marks must be paired consistently. No punctuation (C) leaves the interrupter unclosed and runs into the rest of the sentence. A semicolon (D) cannot pair with the opening dash and wrongly implies a clause break. Answer: A." },
  { id: "t7rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The committee dismissed the warning as ______, only to watch the predicted shortage materialize within months.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["alarmist", "prescient", "accurate", "urgent"], correct: 0, explanation: "The committee 'dismissed the warning,' so the blank must be a dismissive label, and the warning later proved correct ('the predicted shortage materialize[d]'). To dismiss a warning is to call it 'alarmist' (A) — needlessly raising alarm. 'Prescient' (B) means foreseeing the future accurately; you don't dismiss something by calling it prescient (and that would actually praise it). 'Accurate' (C) likewise would not be a reason to dismiss it. 'Urgent' (D) doesn't capture the dismissive judgment; calling a warning urgent would support, not reject, it. Answer: A." },
  { id: "t7rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One scholar argues the city declined because of trade disruption; another insists the cause was a series of droughts. A third proposes that the two causes reinforced each other.", prompt: "Which choice best describes the third scholar's position?", type: "mcq", choices: ["The two proposed causes worked together to produce the decline.", "Neither trade nor drought played any role.", "Only trade disruption mattered.", "The city never actually declined."], correct: 0, explanation: "The third scholar 'proposes that the two causes reinforced each other,' meaning trade disruption and droughts worked together to produce the decline — choice A. B says neither played any role, but the third scholar credits both. C says only trade mattered, which is the first scholar's view, not the third's. D says the city never declined, but all three scholars assume it did. Answer: A." },
  { id: "t7rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The engineers redesigned the valve ______ the original had failed under high pressure during testing.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["valve, the", "valve; the", "valve the", "valve: the"], correct: 1, explanation: "Rule: joining two independent clauses. 'The engineers redesigned the valve' and 'the original had failed under high pressure during testing' are both complete clauses. A semicolon correctly links two related independent clauses, so 'valve; the' (B) is right. 'valve, the' (A) joins them with only a comma — a comma splice. 'valve the' (C) has no punctuation — a run-on. 'valve: the' (D) misuses a colon; a colon introduces an explanation or list following a complete statement, but here the second clause is a coordinate independent clause, better separated by a semicolon. Answer: B." },
  { id: "t7rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the reform's benefits were unevenly shared. ______, wealthy districts gained new schools while poorer ones saw little change.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "Transition logic: the first sentence makes a general point (the reform's benefits were unevenly shared), and the second gives the concrete detail (wealthy districts gained new schools while poorer ones saw little change). A specifying transition fits: 'Specifically' (A). 'In contrast' (B) signals opposition, but the second sentence supports rather than opposes the first. 'Nevertheless' (C) signals concession, which isn't the relationship here. 'Otherwise' (D) means 'if not,' introducing an alternative scenario that doesn't apply. Answer: A." },
  { id: "t7rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than offering a tidy resolution, the playwright leaves the central conflict ______, trusting the audience to weigh the competing claims.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "decided"], correct: 0, explanation: "The clue 'Rather than offering a tidy resolution' and 'trusting the audience to weigh the competing claims' means the playwright leaves the conflict 'unresolved' (A). 'Settled' (B) and 'decided' (D) both mean resolved — the direct opposite of 'rather than offering a … resolution.' 'Trivial' (C) means unimportant, but the text calls it the 'central conflict' and asks the audience to weigh it, so it is significant, not trivial. Answer: A." },
  { id: "t7rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The researcher concedes that her sample was small, but she argues that the effect she found was so large and consistent that it merits a larger follow-up study.", prompt: "Which choice best describes the researcher's reasoning?", type: "mcq", choices: ["She acknowledges a limitation while defending the result's importance.", "She claims her study is flawless.", "She abandons her finding entirely.", "She argues no further study is needed."], correct: 0, explanation: "Reasoning question: the researcher 'concedes that her sample was small' (acknowledges a limitation) 'but … argues that the effect … merits a larger follow-up study' (defends the result's importance). Choice A captures this concede-then-defend move. B says she claims her study is flawless, but she admits a flaw. C says she abandons her finding, yet she defends it. D says she argues no further study is needed, but she calls for a larger follow-up. Answer: A." },
];

// ─────────────────────── PRACTICE TEST 7 · MATH M1 (22) ──────────────────────
const T7_M_M1: SatQuestion[] = [
  { id: "t7m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 7x − 4 = 31, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 7x − 4 = 31 for x. Add 4 to both sides: 7x − 4 + 4 = 31 + 4, giving 7x = 35. Divide both sides by 7: x = 35/7 = 5. Check: 7(5) − 4 = 35 − 4 = 31, which matches. Answer: 5." },
  { id: "t7m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 3 cups of flour for every 12 cookies. How many cups are needed for 20 cookies?", type: "mcq", choices: ["5", "4", "6", "8"], correct: 0, explanation: "Goal: find cups of flour for 20 cookies given 3 cups per 12 cookies. Set up the proportion 3/12 = x/20. The unit rate is 3 ÷ 12 = 0.25 cup per cookie. Multiply by 20 cookies: 0.25 × 20 = 5 cups, which is choice A. Check via cross-multiplication: 3 × 20 = 12 × x → 60 = 12x → x = 5. Trap: choice B (4) comes from mistakenly using 12/3 = 4 cookies-per-cup as if it were cups; that inverts the ratio. Answer: A (5)." },
  { id: "t7m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 2x² − 5, what is the value of f(3)?", type: "mcq", choices: ["13", "1", "31", "7"], correct: 0, explanation: "Goal: evaluate f(x) = 2x² − 5 at x = 3. Substitute: f(3) = 2(3)² − 5. Apply the exponent first (order of operations): 3² = 9. Then 2 × 9 = 18. Finally 18 − 5 = 13, which is choice A. Trap: choice D (7) comes from computing 2 × 3 = 6 first and then 6² style errors, or doing 2·3 − 5 = 1 (choice B), which ignores the exponent. Choice C (31) comes from (2·3)² − 5 = 36 − 5, applying the square to 2x instead of just x. Answer: A (13)." },
  { id: "t7m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 5. What is its diameter?", type: "grid", gridAnswers: ["10"], explanation: "Goal: find the diameter from a radius of 5. The diameter is twice the radius: d = 2r = 2 × 5 = 10. Check: the radius is half the diameter, and 10 ÷ 2 = 5, which matches. Answer: 10." },
  { id: "t7m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 4x − 1 passes through the point (2, k). What is the value of k?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find k, the y-value when the line y = 4x − 1 passes through (2, k). Since the point is on the line, substitute x = 2: k = 4(2) − 1. Compute 4 × 2 = 8, then 8 − 1 = 7. So k = 7. Check: the point (2, 7) satisfies y = 4x − 1 because 4(2) − 1 = 7. Answer: 7." },
  { id: "t7m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 4, 8, and x is 7. What is the value of x?", type: "mcq", choices: ["9", "7", "12", "5"], correct: 0, explanation: "Goal: find x so that the mean of 4, 8, and x is 7. The mean is the sum divided by the count: (4 + 8 + x)/3 = 7. Multiply both sides by 3: 4 + 8 + x = 21, so 12 + x = 21. Subtract 12: x = 9, which is choice A. Check: (4 + 8 + 9)/3 = 21/3 = 7. Trap: choice B (7) just copies the mean itself, forgetting that x must offset the other two values. Answer: A (9)." },
  { id: "t7m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 9 = 25, what is the value of x?", type: "mcq", choices: ["8", "16", "7", "17"], correct: 0, explanation: "Goal: solve 2x + 9 = 25 for x. Subtract 9 from both sides: 2x = 25 − 9 = 16. Divide by 2: x = 16/2 = 8, which is choice A. Check: 2(8) + 9 = 16 + 9 = 25. Trap: choice B (16) stops at 2x = 16 without dividing by 2. Answer: A (8)." },
  { id: "t7m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 7x + 12 = 0?", type: "grid", gridAnswers: ["7"], explanation: "Goal: find the sum of the solutions of x² − 7x + 12 = 0. Factor: we need two numbers that multiply to 12 and add to −7, namely −3 and −4, so (x − 3)(x − 4) = 0. The roots are x = 3 and x = 4, and their sum is 3 + 4 = 7. Shortcut/check: for ax² + bx + c = 0 the sum of roots is −b/a = −(−7)/1 = 7. Answer: 7." },
  { id: "t7m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A shirt's price increased from $20 to $25. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "5%", "125%"], correct: 0, explanation: "Goal: find the percent increase from $20 to $25. Percent increase = (change ÷ original) × 100. The change is 25 − 20 = 5. Divide by the ORIGINAL price: 5/20 = 0.25. Convert to percent: 0.25 × 100 = 25%, which is choice A. Trap: choice B (20%) wrongly divides by the new price (5/25 = 0.20); percent increase always uses the original as the base. Choice C (5%) reports the raw dollar change as a percent. Answer: A (25%)." },
  { id: "t7m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 50° and 70°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["60"], explanation: "Goal: find the third angle of a triangle whose other two angles are 50° and 70°. The interior angles of a triangle sum to 180°. So the third angle = 180 − 50 − 70. Compute 50 + 70 = 120, then 180 − 120 = 60°. Check: 50 + 70 + 60 = 180. Answer: 60." },
  { id: "t7m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A taxi charges a $3 base fare plus $2 per mile. Which equation gives the cost C for m miles?", type: "mcq", choices: ["C = 2m + 3", "C = 3m + 2", "C = 5m", "C = 2m − 3"], correct: 0, explanation: "Goal: model total cost C for m miles. A fixed $3 base fare is a constant (no m attached), and $2 per mile multiplies the number of miles, giving 2m. Total: C = 2m + 3, which is choice A. Trap: choice B (C = 3m + 2) swaps the roles, charging $3 per mile and a $2 base — it misreads which number is per-mile. Choice C (C = 5m) wrongly merges the base and per-mile rate into one coefficient. Answer: A (C = 2m + 3)." },
  { id: "t7m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 3)(x − 2) = x² + bx − 6, what is the value of b?", type: "grid", gridAnswers: ["1"], explanation: "Goal: find b after expanding (x + 3)(x − 2) into the form x² + bx − 6. Use FOIL: First x·x = x²; Outer x·(−2) = −2x; Inner 3·x = 3x; Last 3·(−2) = −6. Combine the middle terms: −2x + 3x = x. So the product is x² + x − 6, meaning the coefficient of x is b = 1. Check: the constant −6 matches the given form, confirming the expansion. Answer: 1." },
  { id: "t7m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 200 people, 35% preferred tea. How many people preferred tea?", type: "mcq", choices: ["70", "65", "35", "140"], correct: 0, explanation: "Goal: find how many of 200 people preferred tea if 35% did. Convert the percent to a decimal: 35% = 0.35. Multiply by the total: 0.35 × 200 = 70, which is choice A. Check: 10% of 200 is 20, so 35% is 3.5 × 20 = 70. Trap: choice C (35) just restates the percent as a count, ignoring the 200 total. Answer: A (70)." },
  { id: "t7m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 4(x − 2) = 2x + 6, what is the value of x?", type: "mcq", choices: ["7", "5", "1", "9"], correct: 0, explanation: "Goal: solve 4(x − 2) = 2x + 6. Distribute the 4 on the left: 4x − 8 = 2x + 6. Subtract 2x from both sides: 2x − 8 = 6. Add 8 to both sides: 2x = 14. Divide by 2: x = 7, which is choice A. Check: left = 4(7 − 2) = 4(5) = 20; right = 2(7) + 6 = 20. They match. Trap: choice B (5) results from forgetting to distribute the 4 to the −2 (using 4x − 2 instead of 4x − 8). Answer: A (7)." },
  { id: "t7m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 10 and width 4. What is its perimeter?", type: "mcq", choices: ["28", "40", "24", "14"], correct: 0, explanation: "Goal: find the perimeter of a rectangle with length 10 and width 4. Perimeter = 2(length + width) = 2(10 + 4) = 2(14) = 28, which is choice A. Check: the four sides are 10 + 4 + 10 + 4 = 28. Trap: choice B (40) multiplies length × width = 10 × 4, which gives the AREA, not the perimeter. Choice C (24) adds the sides incorrectly. Answer: A (28)." },
  { id: "t7m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^(x+1) = 32, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 2^(x+1) = 32. Rewrite 32 as a power of 2: 32 = 2 × 2 × 2 × 2 × 2 = 2^5. So 2^(x+1) = 2^5. Since the bases are equal, set the exponents equal: x + 1 = 5. Subtract 1: x = 4. Check: 2^(4+1) = 2^5 = 32. Answer: 4." },
  { id: "t7m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 25 miles. Two cities are 4 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["100", "75", "50", "125"], correct: 0, explanation: "Goal: find real distance for 4 map inches at a scale of 1 inch = 25 miles. Multiply inches by miles-per-inch: 4 × 25 = 100 miles, which is choice A. Check via proportion: 1/25 = 4/x → x = 4 × 25 = 100. Trap: choice C (50) would be 2 inches, not 4. Answer: A (100)." },
  { id: "t7m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (1, 2) and (5, 14) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope of the line through (1, 2) and (5, 14). Slope = (change in y)/(change in x) = (y₂ − y₁)/(x₂ − x₁) = (14 − 2)/(5 − 1). Compute the numerator 14 − 2 = 12 and the denominator 5 − 1 = 4, so slope = 12/4 = 3. Check: from (1, 2), moving right 4 units to x = 5 should raise y by 4 × 3 = 12, reaching y = 14. Correct. Answer: 3." },
  { id: "t7m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x + 4, what value of x makes f(x) = 19?", type: "mcq", choices: ["5", "7", "6", "4"], correct: 0, explanation: "Goal: find x so that f(x) = 3x + 4 equals 19. Set up 3x + 4 = 19. Subtract 4 from both sides: 3x = 15. Divide by 3: x = 5, which is choice A. Check: f(5) = 3(5) + 4 = 15 + 4 = 19. Trap: choice B (7) comes from subtracting incorrectly (using 19 + 4 then dividing) or a sign slip. Answer: A (5)." },
  { id: "t7m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 6. What is its area, in terms of π?", type: "mcq", choices: ["36π", "12π", "6π", "18π"], correct: 0, explanation: "Goal: find the area of a circle with radius 6, in terms of π. Area = πr². Substitute r = 6: A = π(6)² = π × 36 = 36π, which is choice A. Trap: choice B (12π) uses the circumference formula 2πr = 2π(6), not the area formula. Choice C (6π) just multiplies π by the radius without squaring. Answer: A (36π)." },
  { id: "t7m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 3x − y = 11 and y = 4, what is the value of x?", type: "mcq", choices: ["5", "3", "7", "4"], correct: 0, explanation: "Goal: find x given 3x − y = 11 and y = 4. Substitute y = 4 into the first equation: 3x − 4 = 11. Add 4 to both sides: 3x = 15. Divide by 3: x = 5, which is choice A. Check: 3(5) − 4 = 15 − 4 = 11. Trap: choice C (7) comes from adding y instead of substituting (3x = 11 + 4 + ... miscount) or solving 3x = 21. Answer: A (5)." },
  { id: "t7m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $18 per hour. How much does the worker earn for a 35-hour week?", type: "grid", gridAnswers: ["630"], explanation: "Goal: find weekly earnings at $18/hour for 35 hours. Multiply rate by hours: 18 × 35. Break it up: 18 × 35 = 18 × 30 + 18 × 5 = 540 + 90 = 630 dollars. Check: 35 × 18 = 35 × 18, and 10 × 18 = 180, so 35 × 18 = 3.5 × 180 = 630. Answer: 630." },
];

