const T7_M_M2E: SatQuestion[] = [
  { id: "t7m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 7 = 16, what is the value of x?", type: "grid", gridAnswers: ["9"], explanation: "Goal: solve x + 7 = 16. Subtract 7 from both sides: x = 16 − 7 = 9. Check: 9 + 7 = 16. Answer: 9." },
  { id: "t7m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 10% of 90?", type: "mcq", choices: ["9", "10", "19", "90"], correct: 0, explanation: "Goal: find 10% of 90. 'Of' means multiply, and 10% = 0.10, so 0.10 × 90 = 9, which is choice A. Shortcut: 10% is just moving the decimal one place left, so 90 → 9. Trap: choice B (10) confuses the percent (10) with the result. Answer: A (9)." },
  { id: "t7m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 7 and a width of 3. What is its area?", type: "grid", gridAnswers: ["21"], explanation: "Goal: find the area of a rectangle with length 7 and width 3. Area = length × width = 7 × 3 = 21. Check: that's three rows of 7, or 7 + 7 + 7 = 21. Answer: 21." },
  { id: "t7m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 42, what is the value of x?", type: "mcq", choices: ["7", "6", "48", "36"], correct: 0, explanation: "Goal: solve 6x = 42. Divide both sides by 6: x = 42 ÷ 6 = 7, which is choice A. Check: 6 × 7 = 42. Trap: choice C (48) adds 6 (42 + 6) instead of dividing; choice D (36) subtracts. Answer: A (7)." },
  { id: "t7m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 4² − 1?", type: "grid", gridAnswers: ["15"], explanation: "Goal: evaluate 4² − 1. By order of operations, apply the exponent first: 4² = 4 × 4 = 16. Then subtract: 16 − 1 = 15. Trap: computing (4 − 1)² = 9 would apply the subtraction before the square, which violates order of operations. Answer: 15." },
  { id: "t7m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 6 of its 10 games. What fraction of its games did it win?", type: "mcq", choices: ["3/5", "6/10", "2/5", "1/6"], correct: 0, explanation: "Goal: express games won (6 of 10) as a simplified fraction. The fraction is 6/10. Divide numerator and denominator by their GCF, 2: 6 ÷ 2 = 3 and 10 ÷ 2 = 5, giving 3/5, which is choice A. Note choice B (6/10) is the same value but not simplified, so A is the better answer. Choice C (2/5) and D (1/6) are different values entirely. Answer: A (3/5)." },
  { id: "t7m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 3 = 12, what is the value of x?", type: "grid", gridAnswers: ["15"], explanation: "Goal: solve x − 3 = 12. Add 3 to both sides: x = 12 + 3 = 15. Check: 15 − 3 = 12. Answer: 15." },
  { id: "t7m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 10, 20, and 30?", type: "mcq", choices: ["20", "30", "15", "60"], correct: 0, explanation: "Goal: find the average of 10, 20, and 30. Average = sum ÷ count. Sum = 10 + 20 + 30 = 60; count = 3. So 60 ÷ 3 = 20, which is choice A. Trap: choice D (60) reports the sum without dividing by 3. Answer: A (20)." },
  { id: "t7m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 8. What is its perimeter?", type: "grid", gridAnswers: ["32"], explanation: "Goal: find the perimeter of a square with side length 8. A square has 4 equal sides, so perimeter = 4 × side = 4 × 8 = 32. Check: 8 + 8 + 8 + 8 = 32. Answer: 32." },
  { id: "t7m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 1 = 11, what is the value of x?", type: "mcq", choices: ["5", "6", "10", "4"], correct: 0, explanation: "Goal: solve 2x + 1 = 11. Subtract 1 from both sides: 2x = 10. Divide by 2: x = 5, which is choice A. Check: 2(5) + 1 = 10 + 1 = 11. Trap: choice C (10) stops at 2x = 10 without dividing by 2. Answer: A (5)." },
  { id: "t7m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 5, what is f(7)?", type: "grid", gridAnswers: ["12"], explanation: "Goal: evaluate f(x) = x + 5 at x = 7. Substitute: f(7) = 7 + 5 = 12. Answer: 12." },
  { id: "t7m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 4 pens for $2. How much do 10 pens cost?", type: "mcq", choices: ["$5", "$4", "$8", "$6"], correct: 0, explanation: "Goal: find the cost of 10 pens if 4 pens cost $2. Unit price = $2 ÷ 4 = $0.50 per pen. For 10 pens: 10 × $0.50 = $5, which is choice A. Check via proportion: 4/2 = 10/x → 4x = 20 → x = 5. Trap: choice B ($4) doubles the $2 as if 10 were just twice 4, but 10 is 2.5 times 4. Answer: A ($5)." },
  { id: "t7m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 5x = 35, what is the value of x?", type: "mcq", choices: ["7", "6", "5", "30"], correct: 0, explanation: "Goal: solve 5x = 35. Divide both sides by 5: x = 35 ÷ 5 = 7, which is choice A. Check: 5 × 7 = 35. Trap: choice D (30) subtracts 5 instead of dividing. Answer: A (7)." },
  { id: "t7m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 10 and a height of 6. What is its area?", type: "grid", gridAnswers: ["30"], explanation: "Goal: find the area of a triangle with base 10 and height 6. Area = (1/2) × base × height = (1/2)(10)(6). Compute 10 × 6 = 60, then half of 60 is 30. Trap: forgetting the 1/2 gives 60, which is the area of the enclosing rectangle, not the triangle. Answer: 30." },
  { id: "t7m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 50% of 48?", type: "mcq", choices: ["24", "48", "12", "96"], correct: 0, explanation: "Goal: find 50% of 48. 50% means half, so 0.50 × 48 = 48 ÷ 2 = 24, which is choice A. Trap: choice B (48) restates the number itself; choice D (96) doubles instead of halving. Answer: A (24)." },
  { id: "t7m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/2 = 9, what is the value of x?", type: "grid", gridAnswers: ["18"], explanation: "Goal: solve x/2 = 9. Multiply both sides by 2 to undo the division: x = 9 × 2 = 18. Check: 18/2 = 9. Answer: 18." },
  { id: "t7m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 2³?", type: "mcq", choices: ["8", "6", "9", "16"], correct: 0, explanation: "Goal: evaluate 2³. The exponent 3 means multiply 2 by itself three times: 2 × 2 × 2 = 8, which is choice A. Trap: choice B (6) computes 2 × 3 (treating the exponent as a multiplier); choice D (16) uses 2⁴ by mistake. Answer: A (8)." },
  { id: "t7m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A bus travels 60 miles in 2 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["30", "60", "120", "20"], correct: 0, explanation: "Goal: find average speed for 60 miles in 2 hours. Speed = distance ÷ time = 60 ÷ 2 = 30 miles per hour, which is choice A. Trap: choice B (60) reports the distance as if it were the speed; choice C (120) multiplies instead of dividing. Answer: A (30)." },
  { id: "t7m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x − 6 = 9, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve 3x − 6 = 9. Add 6 to both sides: 3x = 15. Divide by 3: x = 5. Check: 3(5) − 6 = 15 − 6 = 9. Answer: 5." },
  { id: "t7m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 14. What is its radius?", type: "mcq", choices: ["7", "14", "28", "21"], correct: 0, explanation: "Goal: find the radius from a diameter of 14. The radius is half the diameter: r = 14 ÷ 2 = 7, which is choice A. Trap: choice C (28) doubles the diameter instead of halving it. Answer: A (7)." },
  { id: "t7m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 2x and x = 6, what is the value of y?", type: "mcq", choices: ["12", "8", "3", "6"], correct: 0, explanation: "Goal: find y when y = 2x and x = 6. Substitute x = 6: y = 2 × 6 = 12, which is choice A. Trap: choice B (8) adds 2 + 6 instead of multiplying. Answer: A (12)." },
  { id: "t7m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A jar holds 8 red and 12 blue marbles. What fraction of the marbles are red?", type: "mcq", choices: ["2/5", "8/12", "1/2", "3/5"], correct: 0, explanation: "Goal: find the fraction of marbles that are red. Total marbles = 8 red + 12 blue = 20. The red fraction is 8/20. Simplify by dividing top and bottom by 4: 8 ÷ 4 = 2, 20 ÷ 4 = 5, giving 2/5, which is choice A. Trap: choice B (8/12) uses red over blue instead of red over total. Answer: A (2/5)." },
];

