const T7_M_M2H: SatQuestion[] = [
  { id: "t7m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 49 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve x² − 49 = 0 with x > 0. Add 49 to both sides: x² = 49. Take the square root of both sides: x = ±√49 = ±7. The two solutions are 7 and −7, but the condition x > 0 keeps only the positive root, x = 7. Check: 7² − 49 = 49 − 49 = 0. Trap: ignoring x > 0 might tempt −7; the constraint rules it out. Answer: 7." },
  { id: "t7m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 2y = 16 and x − 2y = 0, what is the value of x?", type: "mcq", choices: ["4", "8", "2", "6"], correct: 0, explanation: "Goal: find x from 3x + 2y = 16 and x − 2y = 0. The y-terms are +2y and −2y, so adding the equations eliminates y: (3x + 2y) + (x − 2y) = 16 + 0 → 4x = 16. Divide by 4: x = 4, which is choice A. Check: x − 2y = 0 means y = x/2 = 2; then 3(4) + 2(2) = 12 + 4 = 16. Trap: choice B (8) comes from solving 4x = 16 as x = 16/2 by mistake. Answer: A (4)." },
  { id: "t7m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^x = 81, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve 3^x = 81. Express 81 as a power of 3: 3 × 3 = 9, 9 × 3 = 27, 27 × 3 = 81, so 81 = 3⁴. Then 3^x = 3⁴, and equal bases give x = 4. Check: 3⁴ = 81. Answer: 4." },
  { id: "t7m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A jacket originally priced at $80 is marked up by 25%. What is the new price?", type: "mcq", choices: ["$100", "$105", "$95", "$60"], correct: 0, explanation: "Goal: find the price of an $80 jacket after a 25% markup. The increase is 25% of 80 = 0.25 × 80 = 20. Add it to the original: 80 + 20 = $100, which is choice A. Shortcut: a 25% markup multiplies by 1.25, and 80 × 1.25 = 100. Trap: choice D ($60) subtracts the markup (treating it as a discount). Answer: A ($100)." },
  { id: "t7m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 5 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["13"], explanation: "Goal: find the hypotenuse of a right triangle with legs 5 and 12. Use the Pythagorean theorem: c² = a² + b² = 5² + 12² = 25 + 144 = 169. Take the square root: c = √169 = 13. Check: 5-12-13 is a known Pythagorean triple. Answer: 13." },
  { id: "t7m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 4x − 1, what is the value of p(p(2))?", type: "mcq", choices: ["27", "7", "23", "15"], correct: 0, explanation: "Goal: compute p(p(2)) where p(x) = 4x − 1. Work inside out. First p(2) = 4(2) − 1 = 8 − 1 = 7. Then apply p again to that result: p(7) = 4(7) − 1 = 28 − 1 = 27, which is choice A. Trap: choice B (7) stops after the inner step p(2) = 7 and forgets the outer application. Answer: A (27)." },
  { id: "t7m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 2x + 3y = 13 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["2.2", "11/5"], explanation: "Goal: find y from 2x + 3y = 13 and x = y + 1. Substitute x = y + 1 into the first equation: 2(y + 1) + 3y = 13. Distribute: 2y + 2 + 3y = 13. Combine like terms: 5y + 2 = 13. Subtract 2: 5y = 11. Divide by 5: y = 11/5 = 2.2. Check: x = y + 1 = 3.2; then 2(3.2) + 3(2.2) = 6.4 + 6.6 = 13. Answer: 11/5 (= 2.2)." },
  { id: "t7m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 6x + 5 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find h, the x-coordinate of the vertex of y = x² − 6x + 5. For y = ax² + bx + c, the vertex x-value is h = −b/(2a). Here a = 1 and b = −6, so h = −(−6)/(2·1) = 6/2 = 3. Check: by symmetry the vertex sits halfway between the roots; factoring gives (x − 1)(x − 5), roots 1 and 5, whose midpoint is (1 + 5)/2 = 3. Answer: 3." },
  { id: "t7m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the angle θ has sin θ = 3/5. What is cos θ, given θ is acute?", type: "mcq", choices: ["4/5", "3/4", "5/4", "5/3"], correct: 0, explanation: "Goal: find cos θ given sin θ = 3/5 for an acute angle θ. Sine = opposite/hypotenuse, so opposite = 3 and hypotenuse = 5. Find the adjacent leg with the Pythagorean theorem: adjacent = √(5² − 3²) = √(25 − 9) = √16 = 4. Then cos θ = adjacent/hypotenuse = 4/5, which is choice A. (This is the 3-4-5 right triangle.) Trap: choice B (3/4) gives tan θ (opposite/adjacent), not cosine. Answer: A (4/5)." },
  { id: "t7m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 9 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["6"], explanation: "Goal: find b > 0 making x² + bx + 9 a perfect square trinomial. A perfect square has the form (x + k)² = x² + 2kx + k². Match the constant: k² = 9, so k = 3 (positive). Then the middle term is 2k = 2(3) = 6, so b = 6. Check: (x + 3)² = x² + 6x + 9. Answer: 6." },
  { id: "t7m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −2 and passes through (3, 4). What is its y-intercept?", type: "mcq", choices: ["10", "−2", "4", "6"], correct: 0, explanation: "Goal: find the y-intercept of a line with slope −2 through (3, 4). Use slope-intercept form y = mx + b with m = −2: y = −2x + b. Plug in the point (3, 4): 4 = −2(3) + b → 4 = −6 + b. Add 6: b = 10, which is choice A. Check: y = −2x + 10 gives y = −6 + 10 = 4 at x = 3. Trap: choice B (−2) just copies the slope, not the intercept. Answer: A (10)." },
  { id: "t7m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 20% discount, a laptop costs $480. What was the original price?", type: "mcq", choices: ["$600", "$500", "$576", "$560"], correct: 0, explanation: "Goal: find the original price if a 20% discount leaves $480. A 20% discount means the customer pays 80% of the original: 480 = 0.80 × original. Solve by dividing: original = 480 / 0.80 = 600, which is choice A. Check: 20% of 600 = 120, and 600 − 120 = 480. Trap: choice C ($576) wrongly adds 20% to 480 (480 × 1.2), but you must reverse a discount by dividing by 0.80, not multiplying by 1.20. Answer: A ($600)." },
  { id: "t7m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 36 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-6"], explanation: "Goal: find a < 0 with f(a) = 36 where f(x) = x². Set a² = 36 and take square roots: a = ±√36 = ±6. The condition a < 0 selects the negative root, a = −6. Check: (−6)² = 36. Trap: ignoring a < 0 would give +6; the constraint rules it out. Answer: −6." },
  { id: "t7m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 3 and height 5. What is its volume, in terms of π?", type: "mcq", choices: ["45π", "30π", "15π", "75π"], correct: 0, explanation: "Goal: find the volume of a cylinder with radius 3 and height 5, in terms of π. Volume = πr²h. Square the radius: r² = 3² = 9. Then V = π(9)(5) = 45π, which is choice A. Trap: choice B (30π) uses 2r·h or forgets to square r (using 3 × 2 × 5); the radius must be squared. Answer: A (45π)." },
  { id: "t7m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/3 = 1, what is the value of x?", type: "grid", gridAnswers: ["1.5", "3/2"], explanation: "Goal: solve 1/x + 1/3 = 1 for x. Isolate the 1/x term by subtracting 1/3: 1/x = 1 − 1/3. Write 1 as 3/3: 1/x = 3/3 − 1/3 = 2/3. Now take the reciprocal of both sides: x = 3/2 = 1.5. Check: 1/(3/2) + 1/3 = 2/3 + 1/3 = 1. Answer: 3/2 (= 1.5)." },
  { id: "t7m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 5x + 6 = 0?", type: "mcq", choices: ["6", "5", "−6", "1"], correct: 0, explanation: "Goal: find the product of the solutions of x² − 5x + 6 = 0. Factor: two numbers multiplying to 6 and adding to −5 are −2 and −3, so (x − 2)(x − 3) = 0. The roots are 2 and 3, and their product is 2 × 3 = 6, which is choice A. Shortcut/check: for ax² + bx + c = 0 the product of roots is c/a = 6/1 = 6. Trap: choice B (5) is the SUM of the roots, not the product. Answer: A (6)." },
  { id: "t7m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of cats to dogs in a shelter is 3:5. If there are 40 animals total, how many are dogs?", type: "mcq", choices: ["25", "15", "20", "30"], correct: 0, explanation: "Goal: find the number of dogs when cats:dogs = 3:5 and there are 40 animals total. Add the ratio parts: 3 + 5 = 8 parts. Each part equals 40 ÷ 8 = 5 animals. Dogs are 5 parts: 5 × 5 = 25, which is choice A. Check: cats = 3 × 5 = 15, and 15 + 25 = 40. Trap: choice B (15) is the number of CATS, not dogs. Answer: A (25)." },
  { id: "t7m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:3. If the smaller has area 4, what is the area of the larger?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the larger triangle's area given a 1:3 scale factor and the smaller area of 4. For similar figures, AREAS scale by the SQUARE of the linear scale factor. The linear ratio is 1:3, so the area ratio is 1²:3² = 1:9. Multiply the smaller area by 9: 4 × 9 = 36. Trap: using the linear factor 3 directly (4 × 3 = 12) ignores that area scales by the square. Answer: 36." },
  { id: "t7m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 7) = 4, what is the value of x?", type: "grid", gridAnswers: ["9"], explanation: "Goal: solve √(x + 7) = 4. Square both sides to remove the radical: (√(x + 7))² = 4², so x + 7 = 16. Subtract 7: x = 9. Check: √(9 + 7) = √16 = 4, which matches. Answer: 9." },
  { id: "t7m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x − 3y = 18 and y = 2, what is the value of x?", type: "mcq", choices: ["6", "5", "4", "9"], correct: 0, explanation: "Goal: find x from 4x − 3y = 18 with y = 2. Substitute y = 2: 4x − 3(2) = 18 → 4x − 6 = 18. Add 6 to both sides: 4x = 24. Divide by 4: x = 6, which is choice A. Check: 4(6) − 3(2) = 24 − 6 = 18. Trap: choice B (5) comes from solving 4x = 20 (forgetting to add the 6 correctly). Answer: A (6)." },
  { id: "t7m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 4x + 4, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["2"], explanation: "Goal: find x where g(x) = x² − 4x + 4 equals 0. Factor the trinomial: it is a perfect square, x² − 4x + 4 = (x − 2)². Set (x − 2)² = 0, so x − 2 = 0, giving x = 2 (a double root). Check: g(2) = 4 − 8 + 4 = 0. Answer: 2." },
  { id: "t7m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of bacteria doubles every hour. If it starts at 50, how many are there after 3 hours?", type: "mcq", choices: ["400", "300", "150", "800"], correct: 0, explanation: "Goal: find the bacteria count after 3 hours, starting at 50 and doubling each hour. Doubling for 3 hours multiplies by 2 three times: 2³ = 8. So 50 × 8 = 400, which is choice A. Step-by-step check: hour 1 → 100, hour 2 → 200, hour 3 → 400. Trap: choice B (300) comes from adding 50 three times incorrectly or computing 50 × 2 × 3; doubling is repeated multiplication, not addition. Answer: A (400)." },
];

